//! Generated by `nix run .#update-theme` from arkui/theme.toml: edit that, then run it.
//!
//! The theme's palettes for the desktop: one [`Palette`] per accent, each
//! the shared page, ink and signals with that accent, and its squares. An
//! app installs its own ([`crate::theme::install`]); [`BLUE`] is what is
//! drawn when none is.
use crate::theme::Palette;
use iced::Color;

const fn rgb(r: u8, g: u8, b: u8) -> Color {
    Color::from_rgb8(r, g, b)
}

/// The shared colours of the light side, by role: for what is drawn on one
/// side whatever the theme, as a receipt's paper is.
pub mod light {
    use super::rgb;
    use iced::Color;

    /// The page.
    pub const BACKGROUND: Color = rgb(0xFF, 0xFF, 0xFF);
    /// A plane over the page: a sheet, a card, a bar.
    pub const SURFACE: Color = rgb(0xFF, 0xFF, 0xFF);
    /// The faintest step a container takes off the page.
    pub const CONTAINER_LOWEST: Color = rgb(0xFF, 0xFF, 0xFF);
    /// A container one step off the page.
    pub const CONTAINER_LOW: Color = rgb(0xF7, 0xF7, 0xF7);
    /// A container: a field, a grouped list's rows.
    pub const CONTAINER: Color = rgb(0xF2, 0xF2, 0xF2);
    /// A container a step further: a chip, a track.
    pub const CONTAINER_HIGH: Color = rgb(0xEC, 0xEC, 0xEC);
    /// The furthest step: a pressed row, a meter's track.
    pub const CONTAINER_HIGHEST: Color = rgb(0xE5, 0xE5, 0xE5);
    /// The fill of a glass chip, menu and sheet.
    pub const GLASS: Color = rgb(0xFF, 0xFF, 0xFF);
    /// The edge of a control: a field, an unchecked box.
    pub const OUTLINE: Color = rgb(0x87, 0x87, 0x87);
    /// A divider, and a cover's edge.
    pub const HAIRLINE: Color = rgb(0xE3, 0xE3, 0xE3);
    /// Text.
    pub const INK: Color = rgb(0x1C, 0x1C, 0x1C);
    /// Secondary text: a subtitle, a count, a caption.
    pub const QUIET: Color = rgb(0x5E, 0x5E, 0x5E);
    /// What cannot be pressed.
    pub const DISABLED: Color = rgb(0x9E, 0x9E, 0x9E);
    /// What dims the page under a dialog.
    pub const SCRIM: Color = rgb(0x00, 0x00, 0x00);
    /// A snackbar: the other side's surface.
    pub const INVERSE_SURFACE: Color = rgb(0x2E, 0x2E, 0x2E);
    /// Text on the inverse surface.
    pub const INVERSE_INK: Color = rgb(0xF2, 0xF2, 0xF2);
    /// Wrong: an error, an overspent amount.
    pub const ERROR: Color = rgb(0xB3, 0x26, 0x1E);
    /// What is written on the error colour.
    pub const ON_ERROR: Color = rgb(0xFF, 0xFF, 0xFF);
    /// A quiet container for an error.
    pub const ERROR_CONTAINER: Color = rgb(0xF9, 0xDE, 0xDC);
    /// What is written on that.
    pub const ON_ERROR_CONTAINER: Color = rgb(0x41, 0x0E, 0x0B);
    /// Worth a look: an amount short of its target.
    pub const CAUTION: Color = rgb(0x8A, 0x51, 0x00);
    /// What is written on the caution colour.
    pub const ON_CAUTION: Color = rgb(0xFF, 0xFF, 0xFF);
    /// A quiet container for a caution.
    pub const CAUTION_CONTAINER: Color = rgb(0xFF, 0xE3, 0xC4);
    /// What is written on that.
    pub const ON_CAUTION_CONTAINER: Color = rgb(0x3A, 0x1F, 0x00);
    /// Good: money with a job, a goal met.
    pub const POSITIVE: Color = rgb(0x18, 0x6A, 0x3B);
}

